// Ownership is the ownership model a generated file declares, per ADR 0003
// and docs/generated-application-layout.md.
type Ownership string

const (
	// OwnerNise marks a file Nise regenerates. Hand edits are lost. Such a
	// file carries either NiseOwnedHeader or, for checked-in output from a
	// pinned generator, that tool's standard generated-code marker.
	OwnerNise Ownership = "nise"
	// OwnerApp marks a file the application owns. Nise writes it once and
	// never overwrites it.
	OwnerApp Ownership = "app"
)

// The two ownership headers. Neither records a Nise version: a version in
// the header would rewrite every file on every CLI upgrade and defeat the
// clean-regeneration check.
const (
	// NiseOwnedHeader marks a regenerated file. It matches Go's
	// `^// Code generated .* DO NOT EDIT\.$` convention exactly, which is
	// what makes it machine-readable rather than merely prose.
	NiseOwnedHeader = "Code generated by nise; DO NOT EDIT."
	// AppOwnedHeader marks a file written once and never overwritten.
	AppOwnedHeader = "Generated once by nise; owned by this application. Nise will not overwrite it."

	// OpenAPIGeneratedPath is the sole output whose bytes and ownership
	// marker come directly from the pinned OpenAPI generator.
	OpenAPIGeneratedPath = "internal/platform/httpapi/openapigen/openapi.gen.go"

	// OpenAPITypescriptGeneratedHeader is the standard marker emitted by
	// openapi-typescript. Unlike oapi-codegen's marker it does not carry the
	// tool version; the generated package pin and byte-diff gate provide that
	// reproducibility contract.
	OpenAPITypescriptGeneratedHeader = "This file was auto-generated by openapi-typescript."

	// OpenAPITypescriptGeneratedPath is the checked-in frontend model output.
	OpenAPITypescriptGeneratedPath = "frontend/src/lib/api/schema.d.ts"

	// SQLCGeneratedHeader is the standard marker sqlc writes. Like
	// oapi-codegen's, it is kept as the generator wrote it: rewriting an
	// external tool's header would make an ordinary regeneration dirty.
	// A feature's store/ directory is the structural ownership marker.
	SQLCGeneratedHeader = "Code generated by sqlc. DO NOT EDIT."
)

// IsFeatureQueryPath reports whether path is a feature's hand-written SQL.
//
// Those files carry no ownership header, and declare their ownership by path
// instead. A comment in a query file is not inert: sqlc copies it into the
// generated Go doc comment, so a "Nise will not overwrite it" header placed
// there would appear inside a tool-owned file and contradict that file's own
// marker. queries/ is application-owned and store/ is tool-owned; the two
// directory names are the declaration, which is the same resolution ADR 0009
// applies to files with no comment syntax at all.
func IsFeatureQueryPath(path string) bool {
	const prefix = "internal/features/"
	remainder, found := strings.CutPrefix(path, prefix)
	if !found || !strings.HasSuffix(path, ".sql") {
		return false
	}
	parts := strings.Split(remainder, "/")
	return len(parts) == 3 && parts[0] != "" && parts[1] == "queries"
}

// IsMailTemplatePath reports whether path is one of the application's
// embedded message templates.
//
// Those files carry no ownership header and declare their ownership by path,
// for a stronger version of the reason a feature's query files do. A comment
// in a message template is not inert: the plain-text part is sent verbatim to
// a person, so a header there would arrive in somebody's inbox reading "Nise
// will not overwrite it". The HTML part could hide one in a comment, but a
// pair of files whose ownership is declared two different ways is worse than
// one rule that covers both.
//
// internal/platform/mail/templates/ is application-owned in its entirety, and
// the directory is the declaration — the same resolution ADR 0009 applies to
// JSON, which has no comment syntax at all.
func IsMailTemplatePath(path string) bool {
	const prefix = "internal/platform/mail/templates/"
	remainder, found := strings.CutPrefix(path, prefix)
	if !found || remainder == "" {
		return false
	}
	return !strings.Contains(remainder, "/")
}

// IsSQLCGeneratedPath reports whether path is inside a feature's sqlc output
// directory, which is the structural ownership marker for that tool's files
// (ADR 0014). Everything under internal/features/<feature>/store is replaced
// wholesale by sqlc generate and is never hand-edited.
func IsSQLCGeneratedPath(path string) bool {
	const prefix = "internal/features/"
	remainder, found := strings.CutPrefix(path, prefix)
	if !found || !strings.HasSuffix(path, ".go") {
		return false
	}
	parts := strings.Split(remainder, "/")
	return len(parts) == 3 && parts[0] != "" && parts[1] == "store"
}

// templateRoot is the directory inside the embedded template filesystem
// holding the nise new templates.
const templateRoot = "new"

// templateFile maps one embedded template to the path it is written to.
type templateFile struct {
	// Template is the path inside templates/new, without the leading
	// "new/" and with its .tmpl suffix.
	Template string
	// Output is the generated file's path relative to the project root. It
	// is itself a template, because one output path depends on the
	// application's name.
	Output string
	// Owner is the ownership model the file's own header declares. It is
	// recorded here as well so a test can assert that the header in the
	// rendered bytes and the manifest agree — a header is easy to copy
	// wrong when a template is added by hand.
	Owner Ownership
	// Raw copies the embedded source bytes without running Nise's template
	// engine. It is reserved for vendored templates whose delimiters belong
	// to another pinned generator.
	Raw bool
	// Module names the compile-time module this file belongs to. An empty
	// value means every project gets the file; otherwise it is written only
	// when the recipe selected that module.
	Module recipe.Module
}

// templateFiles is every template nise new renders, sorted by output path.
//
// The mapping is explicit rather than derived from the template's own path
// for two reasons. Four output paths cannot be spelled as template paths
// at all: ".gitignore" and ".env.example" would be swallowed by this
// repository's own .gitignore, ".dockerignore" follows the same naming
// convention so that all three generated dotfiles are spelled one way, and
// cmd/<app>/main.go's directory is not known until generation time. And an
// explicit table is the thing a reviewer can read to know what a generated
// project contains, which a suffix-stripping rule is not.
//
// TestEveryTemplateIsInTheManifest asserts this list and the embedded
// filesystem name exactly the same set of files, so a template added
// without a manifest entry fails the build rather than being silently
// skipped.
