// TemplatePaths returns every template path this package renders, sorted.
// It exists so a test can compare the manifest against the embedded
// filesystem without reaching into unexported state.
func TemplatePaths() []string {
	out := make([]string, 0, len(templateFiles))
	for _, tf := range templateFiles {
		out = append(out, tf.Template)
	}
	return out
}
